import (
	"strings"
	"unicode"
)

// WordFrequency counts how many times each word appears in s.
// A word is a maximal run of Unicode letters or digits. Counting
// is case-insensitive.
func WordFrequency(s string) map[string]int {
	freq := make(map[string]int)

	var sb strings.Builder

	flush := func() {
		if sb.Len() > 0 {
			word := strings.ToLower(sb.String())
			freq[word]++
			sb.Reset()
		}
	}

	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(r)
		} else {
			flush()
		}
	}
	flush()

	return freq
}

export function parseDuration(s: string): number {
  // Overall shape: component (separator component)*
  // component = digits optionally followed by a unit (h, m, s)
  // separator = nothing, whitespace, or a comma optionally surrounded by whitespace
  const fullPattern = /^\d+[hms]?(?:(?:\s*,\s*|\s+)\d+[hms]?)*$/;

  if (typeof s !== "string" || !fullPattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  let total = 0;
  const componentRegex = /\d+[hms]?/g;
  let match: RegExpExecArray | null;

  while ((match = componentRegex.exec(s)) !== null) {
    const token = match[0];
    const unitMatch = token.match(/[hms]$/);

    let value: number;
    let unit: string | null = null;

    if (unitMatch) {
      unit = unitMatch[0];
      value = parseInt(token.slice(0, -1), 10);
    } else {
      value = parseInt(token, 10);
    }

    if (Number.isNaN(value)) {
      throw new Error(`invalid duration: ${s}`);
    }

    switch (unit) {
      case "h":
        total += value * 3600;
        break;
      case "m":
        total += value * 60;
        break;
      case "s":
        total += value;
        break;
      default:
        total += value;
        break;
    }
  }

  return total;
}
